// LibraryAPI over the Rust core (UniFFI `Library`, core/API.md).
// The bindings are generated by tools/mac/build.sh; if the core's names change, fix the mapping here only.
import Foundation
import IthacaCore

@MainActor
final class CoreLibrary: LibraryAPI {
    private let lib: IthacaCore.Library

    init(path: String, deviceId: String) throws {
        do { lib = try IthacaCore.Library.open(path: path, deviceId: deviceId) } catch { throw Self.map(error) }
    }

    func info() -> LibraryInfo {
        let i = lib.info()
        return LibraryInfo(format: Int(i.format), coreVersion: i.coreVersion, readOnly: i.readOnly,
                           migratedFrom: i.migratedFrom.map { Int($0) }, backupPath: i.backupPath, inMemory: false,
                           lockedByOther: i.lockedByOther, problems: i.problems)
    }

    func projects() -> [ProjectSummary] { lib.projects().map(Self.project) }
    func deletedProjects() -> [ProjectSummary] { lib.deletedProjects().map(Self.project) }

    func createProject(title: String, language: ManuscriptLanguage, folders: [String]) throws -> ProjectSummary {
        try call { Self.project(try lib.createProject(title: title, language: Self.lang(language), folders: folders)) }
    }

    func updateProject(id: String, patch: ProjectPatch) throws -> ProjectSummary {
        // API.md: ProjectPatch { title, language, goal }; goal count 0 clears it.
        let goal: IthacaCore.Goal? = patch.goal.map { g in g.map(Self.goal) ?? IthacaCore.Goal(count: 0, basis: .withSpaces) }
        let p = IthacaCore.ProjectPatch(title: patch.title, language: patch.language.map(Self.lang), goal: goal)
        return try call { Self.project(try lib.updateProject(id: id, patch: p)) }
    }

    func deleteProject(id: String) throws { try call { try lib.deleteProject(id: id) } }
    func restoreProject(id: String) throws { try call { try lib.restoreProject(id: id) } }

    func outline(project: String) throws -> Outline {
        try call {
            let o = try lib.outline(project: project)
            return Outline(project: Self.project(o.project), folders: o.folders.map(Self.folder), trash: o.trash.map(Self.sheet))
        }
    }

    func createFolder(project: String, name: String) throws -> FolderInfo { try call { Self.folder(try lib.createFolder(project: project, name: name)) } }
    func renameFolder(project: String, folder: String, name: String) throws { try call { try lib.renameFolder(project: project, folder: folder, name: name) } }
    func deleteFolder(project: String, folder: String) throws { try call { try lib.deleteFolder(project: project, folder: folder) } }
    func restoreFolder(project: String, folder: String) throws { try call { try lib.restoreFolder(project: project, folder: folder) } }

    func createSheet(project: String, folder: String, text: String) throws -> SheetSummary { try call { Self.sheet(try lib.createSheet(project: project, folder: folder, text: text)) } }
    func sheetText(project: String, sheet: String) throws -> String { try call { try lib.sheetText(project: project, sheet: sheet) } }
    func saveSheet(project: String, sheet: String, text: String) throws -> SheetSummary { try call { Self.sheet(try lib.saveSheet(project: project, sheet: sheet, text: text)) } }
    func moveSheet(project: String, sheet: String, folder: String, before: String?) throws { try call { try lib.moveSheet(project: project, sheet: sheet, folder: folder, before: before) } }
    func trashSheet(project: String, sheet: String) throws { try call { try lib.trashSheet(project: project, sheet: sheet) } }
    func restoreSheet(project: String, sheet: String) throws { try call { try lib.restoreSheet(project: project, sheet: sheet) } }
    func deleteSheetForever(project: String, sheet: String) throws { try call { try lib.deleteSheetForever(project: project, sheet: sheet) } }
    func emptyTrash(project: String) throws { try call { try lib.emptyTrash(project: project) } }

    func history(project: String, sheet: String) throws -> [HistoryEntry] {
        try call {
            try lib.history(project: project, sheet: sheet).map {
                HistoryEntry(hash: $0.hash, at: $0.at, device: $0.device, actor: $0.actor == .claude ? .claude : .me,
                             kind: { switch $0 { case .edit: .edit; case .lease: .lease; case .merge: .merge; case .meta: .meta } }($0.kind),
                             added: Int($0.added), removed: Int($0.removed))
            }
        }
    }

    func textAt(project: String, sheet: String, hash: String) throws -> String { try call { try lib.textAt(project: project, sheet: sheet, hash: hash) } }
    func restoreVersion(project: String, sheet: String, hash: String) throws -> SheetSummary { try call { Self.sheet(try lib.restoreVersion(project: project, sheet: sheet, hash: hash)) } }

    func verify(project: String) throws -> IntegrityReport {
        try call {
            let r = try lib.verify(project: project)
            return IntegrityReport(ok: r.ok, blocks: Int(r.blocks), message: r.issues.first.map { "\($0.file): \($0.detail)" })
        }
    }

    func search(query: String, project: String?) -> [SearchHit] { lib.search(query: query, project: project).map(Self.hit) }
    func searchAll(query: String, current: String?) -> [SearchHit] { lib.searchAll(query: query, current: current).map(Self.hit) }

    private static func hit(_ h: IthacaCore.SearchHit) -> SearchHit {
        [h].map {
            SearchHit(project: $0.project, sheet: $0.sheet, title: $0.title, offset: Int($0.offset), length: Int($0.length),
                      before: $0.snippetBefore, match: $0.snippetMatch, after: $0.snippetAfter)
        }[0]
    }

    func importWebBackup(json: String, suffix: String) async throws -> ImportReport {
        let l = lib
        do {
            let r = try await Task.detached(priority: .userInitiated) { try l.importWebBackupWithSuffix(json: json, suffix: suffix) }.value
            return Self.report(r)
        } catch { throw Self.map(error) }
    }

    func importTextFolder(path: String, title: String?, language: ManuscriptLanguage?) async throws -> ImportReport {
        let l = lib
        let lang = language.map(Self.lang)
        do {
            let r = try await Task.detached(priority: .userInitiated) { try l.importTextFolder(path: path, title: title, language: lang) }.value
            return Self.report(r)
        } catch { throw Self.map(error) }
    }

    private static func report(_ r: IthacaCore.ImportReport) -> ImportReport {
        ImportReport(projects: Int(r.projects), folders: Int(r.folders), sheets: Int(r.sheets), skipped: r.skipped)
    }

    func exportText(project: String, sheets: [String], options o: ExportOptions) throws -> String {
        try call {
            try lib.exportText(project: project, sheets: sheets,
                               options: IthacaCore.ExportOptions(blankLine: o.blankLine, indent: o.indent, stripMarkdown: o.stripMarkdown, includeTitle: o.includeTitle, markdown: o.markdown))
        }
    }

    // MARK: Episodes · backups · platform counts (round 2)

    func setEpisode(project: String, sheet: String, info: EpisodeInfo?) throws -> SheetSummary {
        try call { Self.sheet(try lib.setEpisode(project: project, sheet: sheet, info: info.map(Self.episode))) }
    }
    func stock(project: String, folder: String) throws -> Int { try call { Int(try lib.stock(project: project, folder: folder)) } }
    func renumberEpisodes(project: String, folder: String) throws -> Int { try call { Int(try lib.renumberEpisodes(project: project, folder: folder)) } }

    func backupDue() -> Bool { lib.backupDue() }

    func backupNow() async throws -> BackupInfo {
        let l = lib
        do { return Self.backup(try await Task.detached(priority: .utility) { try l.backupNow() }.value) } catch { throw Self.map(error) }
    }

    func backupManual() async throws -> BackupInfo {
        let l = lib
        do { return Self.backup(try await Task.detached(priority: .userInitiated) { try l.backupManual() }.value) } catch { throw Self.map(error) }
    }

    func backups() -> [BackupInfo] { lib.backups().map(Self.backup) }
    func backupsDir() -> String { lib.backupsDir() }
    func restoreBackupAsCopies(path: String, suffix: String) async throws -> [ProjectSummary] {
        let l = lib
        do { return try await Task.detached(priority: .userInitiated) { try l.restoreBackupAsCopiesWithSuffix(path: path, suffix: suffix) }.value.map(Self.project) } catch { throw Self.map(error) }
    }

    // MARK: qa1 (core/API.md "(added: qa1)")

    func setStatusThrough(project: String, folder: String, sheet: String, status: EpisodeStatus) throws -> Int {
        try call { Int(try lib.setStatusThrough(project: project, folder: folder, sheet: sheet, status: Self.episode(EpisodeInfo(status: status)).status)) }
    }

    func recoverSheetFromBackup(project: String, sheet: String) throws -> SheetSummary {
        try call { Self.sheet(try lib.recoverSheetFromBackup(project: project, sheet: sheet)) }
    }

    func keepLastGoodText(project: String, sheet: String) throws -> SheetSummary {
        try call { Self.sheet(try lib.keepLastGoodText(project: project, sheet: sheet)) }
    }

    func countFor(text: String, rule: CountRule) -> Int {
        let r: IthacaCore.CountRule = switch rule {
        case .withSpaces: .withSpaces
        case .withoutSpaces: .withoutSpaces
        case .words: .words
        case .munpia: .munpia
        case .novelpia: .novelpia
        case .bytesUtf8: .bytesUtf8
        }
        return Int(IthacaCore.countFor(text: text, rule: r))
    }

    func munpiaPages(text: String) -> Int { Int(IthacaCore.munpiaPages(text: text)) }

    // MARK: r3 (core/API.md "(added: r3)")

    func goalCount(text: String, basis: GoalBasis) -> Int { Int(IthacaCore.goalCount(text: text, basis: Self.basis(basis))) }

    func nextRelease(project: String, folder: String) throws -> Int64? {
        try call { try lib.nextRelease(project: project, folder: folder) }
    }

    func folderStats(project: String, folder: String) throws -> FolderStats {
        try call {
            let f = try lib.folderStats(project: project, folder: folder)
            return FolderStats(sheets: Int(f.sheets), episodes: Int(f.episodes),
                               counts: Counts(chars: Int(f.total.chars), charsNoSpace: Int(f.total.charsNoSpace), words: Int(f.total.words), paragraphs: Int(f.total.paragraphs)),
                               averageChars: Int(f.averageChars), munpia: Int(f.munpiaTotal), novelpia: Int(f.novelpiaTotal),
                               published: Int(f.published), scheduled: Int(f.scheduled), drafts: Int(f.drafts))
        }
    }

    func mcpSettings() -> McpSettings {
        let m = lib.mcpSettings()
        return McpSettings(enabled: m.enabled, projects: m.projects)
    }

    func setMcpSettings(_ settings: McpSettings) throws -> McpSettings {
        try call {
            let m = try lib.setMcpSettings(enabled: settings.enabled, projects: settings.projects)
            return McpSettings(enabled: m.enabled, projects: m.projects)
        }
    }

    private static func backup(_ b: IthacaCore.BackupInfo) -> BackupInfo {
        BackupInfo(path: b.path, at: b.at, bytes: b.bytes, kind: { switch b.kind { case .auto: .auto; case .manual: .manual; case .preMigration: .preMigration } }(), projects: Int(b.projects))
    }

    private static func episode(_ e: EpisodeInfo) -> IthacaCore.EpisodeInfo {
        IthacaCore.EpisodeInfo(number: e.number.map { UInt32($0) }, status: { switch e.status { case .draft: .draft; case .revising: .revising; case .scheduled: .scheduled; case .published: .published } }(),
                               publishAt: e.publishAt, platform: e.platform, excluded: e.excluded)
    }

    private static func episode(_ e: IthacaCore.EpisodeInfo) -> EpisodeInfo {
        EpisodeInfo(number: e.number.map { Int($0) }, status: { switch e.status { case .draft: .draft; case .revising: .revising; case .scheduled: .scheduled; case .published: .published } }(),
                    publishAt: e.publishAt, platform: e.platform, excluded: e.excluded)
    }

    // MARK: Mapping

    private func call<T>(_ f: () throws -> T) throws -> T {
        do { return try f() } catch { throw Self.map(error) }
    }

    private static func map(_ e: Error) -> LibraryError {
        guard let (kind, m) = coreErrorInfo(e) else { return .io("\(e)") }
        switch kind {
        case .notFound: return .notFound
        case .readOnly: return .readOnly
        case .invalidInput: return .invalidInput(m)
        case .io: return .io(m)
        case .corrupt: return .corrupt(m)
        }
    }

    private static func lang(_ l: ManuscriptLanguage) -> IthacaCore.Language { l == .ko ? .ko : .en }
    private static func goal(_ g: Goal) -> IthacaCore.Goal { IthacaCore.Goal(count: UInt32(g.count), basis: basis(g.basis)) }

    private static func basis(_ b: GoalBasis) -> IthacaCore.GoalBasis {
        switch b {
        case .withSpaces: .withSpaces
        case .withoutSpaces: .withoutSpaces
        case .words: .words
        case .munpia: .munpia
        case .novelpia: .novelpia
        }
    }

    private static func basis(_ b: IthacaCore.GoalBasis) -> GoalBasis {
        switch b {
        case .withSpaces: .withSpaces
        case .withoutSpaces: .withoutSpaces
        case .words: .words
        case .munpia: .munpia
        case .novelpia: .novelpia
        }
    }

    private static func project(_ p: IthacaCore.ProjectSummary) -> ProjectSummary {
        let goal = p.goal.flatMap { g -> Goal? in
            g.count == 0 ? nil : Goal(count: Int(g.count), basis: basis(g.basis))
        }
        return ProjectSummary(id: p.id, title: p.title, language: p.language == .ko ? .ko : .en, goal: goal, created: p.created, deleted: p.deleted)
    }

    private static func folder(_ f: IthacaCore.FolderInfo) -> FolderInfo {
        FolderInfo(id: f.id, name: f.name, order: Int(f.order), sheets: f.sheets.map(sheet))
    }

    private static func sheet(_ s: IthacaCore.SheetSummary) -> SheetSummary {
        SheetSummary(id: s.id, folder: s.folder, order: Int(s.order), title: s.title, excerpt: s.excerpt,
                     counts: Counts(chars: Int(s.counts.chars), charsNoSpace: Int(s.counts.charsNoSpace), words: Int(s.counts.words), paragraphs: Int(s.counts.paragraphs)),
                     created: s.created, modified: s.modified, trashed: s.trashed, branched: s.branched, episode: s.episode.map(episode), damaged: s.damaged)
    }
}
